from lesson import *
import algos7

UNIT = Unit(7, "Basic Data Structures", "Lists: store many values under one name, change them, loop through them, search them, and choose good algorithms.",
    "Big Idea 3: Algorithms and Programming", "#DB2777", "#BE185D", "#F472B6", "#FCE7F3", "code",
    ["Make a list, read items by index, and change them", "Add and remove items and watch the length change", "Loop through a list to total, count, find the largest, and average", "Simulate random events with lists", "Search a list with linear and binary search and compare their efficiency", "Explain how a list manages complexity in the Create Task", "Compare algorithms, reasonable time, heuristics, and undecidable problems"],
    [
    L("7.1", "Make a list, read items with an index, and change an item.",
      [("list", "an ordered row of values inside square brackets"), ("item (element)", "one value in a list"), ("index", "the position of an item; the first item is at index 0 in Python"), ("IndexError", "the error for an index that is past the end of the list")],
      [("A list holds many values", """A **list** stores many values under **one name**. You write it with square brackets and commas: `colors = ["red", "green", "blue"]`. Each value is an **item** (the exam also says **element**). A list can hold numbers, strings, or both, and `len(colors)` tells you how many items it has (3)."""),
       ("Get one item with an index", """Every item has an **index**, its position. Just like strings, the first item is at index **0**. `colors[0]` is `"red"`, `colors[1]` is `"green"`, and `colors[-1]` (a negative index counts from the end) is `"blue"`. The last index is always `len(colors) - 1`."""),
       ("Change an item", """Unlike a string, a list **can be changed**. `colors[1] = "gold"` replaces the item at index 1. The list now holds red, gold, blue."""),
       ("A list of numbers", """A list of numbers works the same way, and you can do math with its items: `nums[0] + nums[2]`. You can also take a slice: `colors[0:2]` gives the first two items (the stop index is not included, just as in strings)."""),
       ("An index that does not exist", """If you ask for an index past the end, Python stops with an **IndexError: list index out of range**. For a list of 3 items the indexes are 0, 1, and 2, so `colors[3]` is an error.

!warn: On the exam, lists start at index **1**. `fruit[1]` is the **first** item. In Python, the first item is `fruit[0]`. This is the number one thing to keep straight."""),
      ],
      [A("Make, read, and change", 'colors = ["red", "green", "blue"]\nprint(colors[0])\nprint(colors[-1])\ncolors[1] = "gold"\nprint(colors)',
         [(0, "[", "A list: square brackets, commas."), (1, "[0]", "First item (index 0)."), (2, "[-1]", "Last item."), (3, "[1] =", "Replace the item at index 1.")], out="red\nblue\n['red', 'gold', 'blue']", cap="Indexes start at 0, and a list can be changed in place."),
       A("A list of numbers", 'nums = [10, 20, 30]\ntotal = nums[0] + nums[2]\nprint(total)\nprint(len(nums))',
         [(1, "nums[0] + nums[2]", "10 + 30."), (3, "len(nums)", "How many items: 3.")], out="40\n3", cap="Items can be used in math like any value."),
       anatomy("Python index versus exam index", [("red", "0 / 1", "Python 0, exam 1"), ("green", "1 / 2", ""), ("blue", "2 / 3", "")], size=28, mono=True, caption="The same list, two numbering systems: Python starts at 0 and the exam starts at 1.")],
      [T("Read and change", 'colors = ["red", "green", "blue"]\nfirst = colors[0]\nlast = colors[-1]\ncolors[1] = "gold"', ['1| colors=["red", "green", "blue"]', '2| first="red"', '3| last="blue"', '4| colors=["red", "gold", "blue"]'], cap="Reading an item does not change the list. Line 4 replaces the item at index 1."),
       T("Numbers in a list", 'nums = [10, 20, 30]\ntotal = nums[0] + nums[2]\nnums[1] = nums[1] + 5\nsize = len(nums)', ['1| nums=[10, 20, 30]', '2| total=40', '3| nums=[10, 25, 30]', '4| size=3'], cap="total uses the items at index 0 and 2. Line 3 adds 5 to the middle item."),
       T("An index that does not exist", 'names = ["Ana", "Ben"]\nx = names[1]\ny = names[2]', ['1| names=["Ana", "Ben"]', '2| x="Ben"'], out="IndexError: list index out of range", cap="Two items means indexes 0 and 1. Line 3 asks for index 2, which does not exist, so Python stops."),
       T("A slice of a list", 'nums = [5, 6, 7, 8, 9]\npart = nums[1:4]\ntail = nums[-2:]', ['1| nums=[5, 6, 7, 8, 9]', '2| part=[6, 7, 8]', '3| tail=[8, 9]'], cap="nums[1:4] uses indexes 1, 2, 3 (the stop is not included). nums[-2:] is the last two items.")],
      [("`colors[1]` expecting the first item", "Python starts at 0, so index 1 is the second item.", "`colors[0]`"), ("`colors[3]` in a 3-item list", "IndexError: the last index is 2.", "`colors[len(colors) - 1]` or `colors[-1]`"), ("`colors(0)`", "Round brackets mean a function call: TypeError.", "Square brackets: `colors[0]`"), ("`colors = [\"red\" \"blue\"]`", "A missing comma joins them into one string.", "Put commas between items"),
       ("Treating the exam's index 1 like Python's", "Off by one on the exam.", "Exam first item is 1, Python's is 0"), ("`colors[1.5]`", "An index must be a whole number: TypeError.", "Use an int"), ("`colors[0] = \"x\"` on a string", "Strings cannot be changed in place (lists can).", "Build a new string"), ("Empty list: `[][0]`", "IndexError: there is nothing there.", "Check the length first")],
      ["Lists on the exam start at index **1**. `list[i]` is the item at position i.", "A list manages complexity: one name for many values.", "An index outside the list (below 1 or above LENGTH) is an error."],
      [Q("What does `[\"a\", \"b\", \"c\"][1]` give in Python?", ["`\"a\"`", "`\"b\"`", "`\"c\"`", "an error"], 1, "Python indexes start at 0, so index 1 is the second item."),
       Q("What does `len([4, 8, 15, 16])` give?", ["3", "4", "16", "15"], 1, "It counts the items."),
       Q("What does this print?", ["red", "gold", "blue", "an error"], 1, "Index 1 was replaced.", 'colors = ["red", "blue"]\ncolors[1] = "gold"\nprint(colors[1])'),
       Q("On the exam, `fruit[1]` is...", ["The first item", "The second item", "The last item", "An error"], 0, "Exam lists start at 1.")]),

    L("7.2", "Add items to a list, insert at a position, remove items, and watch the length change.",
      [("`append()`", "adds an item at the end of the list"), ("`insert(i, x)`", "adds item x at index i, pushing the others over"), ("`pop(i)`", "removes the item at index i and gives it back"), ("`len()`", "the number of items")],
      [("Start empty and append", """A list can start **empty**: `names = []`. The `.append(item)` method adds an item to the **end**. `names.append("Ana")` makes `["Ana"]`, and appending again adds the next one after it. This is how you build a list while a program runs."""),
       ("Append inside a loop", """Put `.append()` in a loop to build a list: `for i in range(3): nums.append(i * 10)` makes `[0, 10, 20]`."""),
       ("Insert at a position", """`.insert(index, item)` puts the item **at that index** and pushes everything after it one place over. `colors.insert(1, "gold")` on `["red", "blue", "green"]` gives `["red", "gold", "blue", "green"]`."""),
       ("Remove an item", """`.pop(index)` removes the item at that index. It also **gives the item back**, so you can store it: `gone = colors.pop(0)`. The items after it move up to fill the gap."""),
       ("Watch the length change", """`len()` always tells you the current number of items. It goes **up by 1** with each append or insert and **down by 1** with each pop."""),
       ("The exam's list operations", """On the exam the operations are `APPEND(list, value)`, `INSERT(list, i, value)`, and `REMOVE(list, i)`, with `LENGTH(list)` and indexes that start at **1**. `INSERT(fruit, 1, "fig")` puts fig at the **front**."""),
      ],
      [A("Append builds a list", 'nums = []\nfor i in range(3):\n    nums.append(i * 10)\nprint(nums)',
         [(0, "[]", "An empty list."), (2, "append", "Adds to the END.")], out="[0, 10, 20]", cap="The list grows by one each pass."),
       A("Insert and pop", 'colors = ["red", "blue", "green"]\ncolors.insert(1, "gold")\nprint(colors)\ngone = colors.pop(0)\nprint(gone, colors)',
         [(1, "insert(1,", "Goes to index 1; blue moves over."), (3, "pop(0)", "Removes index 0 and gives it back.")], out="['red', 'gold', 'blue', 'green']\nred ['gold', 'blue', 'green']", cap="insert and pop use indexes, and the other items shift."),
       A("Length changes", 'guests = ["Ana", "Ben"]\nguests.append("Cy")\nguests.pop(0)\nprint(len(guests))',
         [(1, "append", "length 2 to 3."), (2, "pop(0)", "length 3 to 2.")], out="2", cap="Each add or remove changes the length by one.")],
      [T("Append in a loop", 'nums = []\nfor i in range(3):\n    nums.append(i * 10)', ['1| nums=[]', '2| i=0', '3| nums=[0]', '2| i=1', '3| nums=[0, 10]', '2| i=2', '3| nums=[0, 10, 20]'], cap="The list starts empty. Each pass appends i * 10 to the end."),
       T("Insert and pop", 'colors = ["red", "blue", "green"]\ncolors.insert(1, "gold")\ngone = colors.pop(0)', ['1| colors=["red", "blue", "green"]', '2| colors=["red", "gold", "blue", "green"]', '3| gone="red"; colors=["gold", "blue", "green"]'], cap="insert puts gold at index 1 and pushes blue and green over. pop(0) removes red and returns it."),
       T("Length changes", 'guests = ["Ana", "Ben"]\nn1 = len(guests)\nguests.append("Cy")\nn2 = len(guests)\nguests.pop(0)\nn3 = len(guests)', ['1| guests=["Ana", "Ben"]', '2| n1=2', '3| guests=["Ana", "Ben", "Cy"]', '4| n2=3', '5| guests=["Ben", "Cy"]', '6| n3=2'], cap="Length goes 2, 3, then back to 2."),
       T("The exam's operations (index starts at 1)", 'fruit ← ["apple", "pear"]\nAPPEND(fruit, "plum")\nINSERT(fruit, 1, "fig")\nREMOVE(fruit, 2)\nDISPLAY(fruit[2])\nDISPLAY(LENGTH(fruit))', ['1| fruit=["apple", "pear"]', '2| fruit=["apple", "pear", "plum"]', '3| fruit=["fig", "apple", "pear", "plum"]', '4| fruit=["fig", "pear", "plum"]'], check=False, out="pear\n3", cap="INSERT at position 1 puts fig first. REMOVE at position 2 removes apple. Then fruit[2] is pear, and the length is 3.")],
      [("`nums = nums.append(5)`", "`append` changes the list in place and returns None, so nums becomes None.", "`nums.append(5)` on its own line"), ("`nums.add(5)`", "Lists have no `add`: AttributeError.", "`nums.append(5)`"), ("`nums.append[5]`", "Square brackets instead of round: TypeError.", "`nums.append(5)`"), ("`names.pop(5)` on a short list", "IndexError: pop index out of range.", "Check the length first"),
       ("`pop()` from an empty list", "IndexError: pop from empty list.", "Make sure the list is not empty"), ("Using `insert` and expecting the end", "insert puts the item at the index you give.", "`append` for the end"), ("Expecting the old items to stay at the same index", "After a pop or insert the items shift.", "Trace the list after each change"), ("Exam index 1 vs Python index 0", "INSERT(fruit, 1, x) is the front on the exam.", "Convert by one")],
      ["The exam's list operations: `APPEND(list, value)`, `INSERT(list, i, value)`, `REMOVE(list, i)`, and `LENGTH(list)`.", "Indexes on the exam start at 1. Insert and remove shift the other items.", "Trace the list after every operation."],
      [Q("What is `[1, 2, 3]` after `append(4)`?", ["`[4, 1, 2, 3]`", "`[1, 2, 3, 4]`", "`[1, 2, 4]`", "`[4]`"], 1, "append adds to the end."),
       Q("What does `colors.pop(0)` do to `[\"a\", \"b\", \"c\"]`?", ["Removes \"a\" and gives it back", "Removes \"c\"", "Adds a 0", "Nothing"], 0, "It removes the item at index 0 and returns it."),
       Q("What does this print?", ["2", "3", "4", "1"], 0, "Two appends make 4 items... then one pop leaves 3. Start with 1: 1 + 2 - 1 = 2.", 'a = [1]\na.append(2)\na.append(3)\na.pop(0)\nprint(len(a))'),
       Q("After `names = [\"A\", \"B\"]` and `names.insert(1, \"X\")`, what is `names`?", ["`[\"A\", \"X\", \"B\"]`", "`[\"X\", \"A\", \"B\"]`", "`[\"A\", \"B\", \"X\"]`", "`[\"A\", \"B\"]`"], 0, "X goes to index 1, pushing B over.")]),

    L("7.3", "Loop through a list to visit, total, count, find the largest, and average.",
      [("traverse", "visit every item in a list, one at a time"), ("accumulator", "a variable that builds up a result as the loop runs"), ("largest (maximum)", "the biggest item; start with the first and keep any bigger one"), ("`FOR EACH`", "the exam's loop that visits every item in a list")],
      [("Visit every item", """A `for` loop can visit every item in a list: `for score in scores:`. The loop variable holds each item in turn. This is the exam's `FOR EACH item IN list`."""),
       ("The sum pattern", """To add the items up, make a `total = 0` before the loop, and add each item inside it: `total = total + score`."""),
       ("Count the matches", """To count only some items, put an `if` inside the loop and add 1 to a counter when the item passes the test."""),
       ("Find the largest", """Start with the first item as the best so far (`best = scores[0]`), then check each item: if it is bigger than `best`, it becomes the new `best`."""),
       ("Find the average", """The average is the total divided by the number of items: `total / len(scores)`."""),
       ("Loop with the index", """If you also need the position, loop over `range(len(scores))` and read `scores[i]`. Remember that positions start at 0."""),
      ],
      [A("Sum and average", 'scores = [80, 90, 70]\ntotal = 0\nfor score in scores:\n    total = total + score\nprint(total / len(scores))',
         [(1, "total = 0", "Start before the loop."), (3, "total + score", "Add each item."), (4, "len(scores)", "How many items.")], out="80.0", cap="240 / 3 is 80.0."),
       A("Find the largest", 'scores = [80, 95, 70]\nbest = scores[0]\nfor score in scores:\n    if score > best:\n        best = score',
         [(1, "scores[0]", "Start with the first."), (3, "score > best", "Only a bigger one replaces it.")], cap="best ends as 95."),
       A("Loop with the index", 'names = ["Ana", "Ben"]\nfor i in range(len(names)):\n    print(i, names[i])',
         [(1, "range(len(names))", "0 up to len - 1."), (2, "names[i]", "The item at position i.")], out="0 Ana\n1 Ben", cap="Use this when you need the position too.")],
      [T("Sum", 'scores = [80, 90, 70]\ntotal = 0\nfor score in scores:\n    total = total + score', ['1| scores=[80, 90, 70]', '2| total=0', '3| score=80', '4| total=80', '3| score=90', '4| total=170', '3| score=70', '4| total=240'], cap="total grows with each item: 0, 80, 170, 240."),
       T("Count the matches", 'scores = [80, 55, 95, 60]\npassed = 0\nfor s in scores:\n    if s >= 60:\n        passed = passed + 1', ['1| scores=[80, 55, 95, 60]', '2| passed=0', '3| s=80', '5| passed=1', '3| s=55', '3| s=95', '5| passed=2', '3| s=60', '5| passed=3'], cap="55 fails the test. The other three pass, so passed ends at 3."),
       T("Find the largest", 'scores = [80, 95, 70]\nbest = scores[0]\nfor score in scores:\n    if score > best:\n        best = score', ['1| scores=[80, 95, 70]', '2| best=80', '3| score=80', '3| score=95', '5| best=95', '3| score=70'], cap="95 beats 80, so best becomes 95. 70 does not beat 95."),
       T("Average", 'prices = [4, 6, 8, 10]\ntotal = 0\nfor price in prices:\n    total = total + price\navg = total / len(prices)', ['1| prices=[4, 6, 8, 10]', '2| total=0', '3| price=4', '4| total=4', '3| price=6', '4| total=10', '3| price=8', '4| total=18', '3| price=10', '4| total=28', '5| avg=7.0'], cap="28 divided by 4 items is 7.0.")],
      [("`total = 0` inside the loop", "It resets every pass.", "Put it before the loop"), ("Starting `best = 0` for negative data", "If all items are negative, 0 wrongly wins.", "`best = scores[0]`"), ("Dividing by the wrong count", "`total / 3` breaks when the list grows.", "`total / len(scores)`"), ("`for i in scores: scores[i]`", "i holds an item, not an index.", "Use `range(len(scores))` or the item directly"),
       ("Using `>=` for \"largest\"", "It works but replaces on ties.", "`>` is fine"), ("Printing inside the loop", "It prints every pass.", "Print after the loop"), ("`len` without brackets", "SyntaxError / TypeError.", "`len(scores)`"), ("Averaging an empty list", "ZeroDivisionError.", "Make sure there is at least one item")],
      ["The exam's `FOR EACH item IN list` visits every item. Know how to total, count, and find the largest.", "Traversing a list and updating a variable is a very common exam question.", "An algorithm can use sequencing, selection, and iteration together."],
      [Q("What is `total` at the end?", ["6", "9", "12", "3"], 1, "2 + 3 + 4.", 'total = 0\nfor n in [2, 3, 4]:\n    total = total + n'),
       Q("To find the largest item, `best` should start as...", ["0", "the first item", "the last item", "-1"], 1, "Start with the first item so it works for any data."),
       Q("Which expression gives the average of `nums`?", ["`sum(nums)`", "`sum(nums) / len(nums)`", "`len(nums) / sum(nums)`", "`max(nums)`"], 1, "Total divided by count."),
       Q("What does this print?", ["2", "3", "4", "0"], 0, "Only 6 and 9 are greater than 5.", 'c = 0\nfor n in [3, 6, 9, 4]:\n    if n > 5:\n        c = c + 1\nprint(c)')]),

    L("7.4", "Use random numbers and lists to simulate things like coin flips, dice, and free throws.",
      [("simulation", "a program that models a real event using random numbers"), ("trial", "one run of the event"), ("tally", "a list of counters, one for each possible result"), ("`RANDOM(a, b)`", "the exam's random whole number from a to b, both ends included")],
      [("A random number", """A **simulation** uses randomness to model a real event. `random.randint(1, 6)` rolls a die (both ends are included), and each result is equally likely."""),
       ("A random item from a list", """`random.choice(list)` picks one item at random: `random.choice(["heads", "tails"])`."""),
       ("Many flips in a list", """Loop and **append** each result to a list to keep every flip. Then you can count them."""),
       ("Tally the dice", """A **tally** list holds one counter for each possible result. For a die, `counts = [0, 0, 0, 0, 0, 0]`. A roll of 3 adds 1 to `counts[roll - 1]`, because the roll starts at 1 but list indexes start at 0."""),
       ("Simulate a free throw", """A 70 percent shooter can be simulated with `random.randint(1, 10) <= 7`. That is True for 1 through 7, which is 7 out of 10 outcomes."""),
       ("More trials, better answer", """With only a few trials the results bounce around. The more times you repeat, the closer the percent gets to the true 70."""),
      ],
      [A("Tally the dice", 'import random\ncounts = [0, 0, 0, 0, 0, 0]\nfor i in range(60):\n    r = random.randint(1, 6) - 1\n    counts[r] = counts[r] + 1',
         [(1, "[0, 0, 0, 0, 0, 0]", "One counter per face."), (3, "- 1", "Face 1 uses index 0.")], cap="A roll of 6 adds to index 5.", check=False),
       A("Simulate a free throw", 'import random\nmade = 0\nfor shot in range(100):\n    if random.randint(1, 10) <= 7:\n        made = made + 1',
         [(3, "<= 7", "True for 1 to 7: 70 percent of outcomes.")], cap="made is usually near 70, but changes each run.", check=False),
       A("Pretend draws", 'draws = [7, 3, 9, 10, 1]\nmade = 0\nfor d in draws:\n    if d <= 7:\n        made = made + 1\nprint(made)',
         [(3, "d <= 7", "Counts a made shot.")], out="3", cap="The same logic with fixed numbers, so you can trace it.")],
      [T("Tally a fixed set of rolls", 'counts = [0, 0, 0, 0, 0, 0]\nfor roll in [3, 6, 3, 1]:\n    counts[roll - 1] = counts[roll - 1] + 1', ['1| counts=[0, 0, 0, 0, 0, 0]', '2| roll=3', '3| counts=[0, 0, 1, 0, 0, 0]', '2| roll=6', '3| counts=[0, 0, 1, 0, 0, 1]', '2| roll=3', '3| counts=[0, 0, 2, 0, 0, 1]', '2| roll=1', '3| counts=[1, 0, 2, 0, 0, 1]'], cap="A roll of 3 adds to index 2. A 6 adds to index 5. So after four rolls counts is [1, 0, 2, 0, 0, 1]."),
       T("Free throws with pretend draws", 'draws = [7, 3, 9, 10, 1]\nmade = 0\nfor d in draws:\n    if d <= 7:\n        made = made + 1', ['1| draws=[7, 3, 9, 10, 1]', '2| made=0', '3| d=7', '5| made=1', '3| d=3', '5| made=2', '3| d=9', '3| d=10', '3| d=1', '5| made=3'], cap="Draws of 7, 3, and 1 are made shots (3 of 5). 9 and 10 are misses."),
       T("Coin flips in a list", 'flips = [0, 1, 1, 0, 1]\nheads = 0\nfor f in flips:\n    if f == 1:\n        heads = heads + 1', ['1| flips=[0, 1, 1, 0, 1]', '2| heads=0', '3| f=0', '3| f=1', '5| heads=1', '3| f=1', '5| heads=2', '3| f=0', '3| f=1', '5| heads=3'], cap="Heads is 1. Three of the five flips are heads.")],
      [("`counts[roll]` for a roll of 6", "IndexError: the last index is 5.", "`counts[roll - 1]`"), ("Too few trials", "The percent is far from the true value.", "Use many trials"), ("Expecting exactly 50 percent", "Random results vary.", "Expect close, not exact"), ("`randint(1, 10) < 7` for 70%", "That is 6 out of 10, 60 percent.", "Use `<= 7`"),
       ("Forgetting `import random`", "NameError.", "Import at the top"), ("Starting the tally as `[]`", "There is nothing to add to.", "Start with a zero for every outcome"), ("Calling randint once outside the loop", "Every trial uses the same number.", "Call it inside the loop"), ("Using a simulation to prove one answer", "It estimates.", "More trials give a better estimate")],
      ["A **simulation** is a program that models a real event, usually with random numbers. It can include less detail than the real thing and it lets you test without real-world cost.", "`RANDOM(a, b)` includes both ends. A question asks which results could happen.", "Simulations help study things that are too slow, costly, or dangerous to try."],
      [Q("What is a simulation?", ["A program that models a real event, often using random numbers", "A kind of loop", "A list", "A syntax error"], 0, "Simulations model real events."),
       Q("Why use `counts[roll - 1]`?", ["Rolls start at 1 but list indexes start at 0", "It is faster", "Rolls start at 0", "It is required by random"], 0, "A roll of 1 goes at index 0."),
       Q("Which gives a 70 percent chance with `randint(1, 10)`?", ["`<= 7`", "`< 7`", "`== 7`", "`> 7`"], 0, "1 through 7 is 7 of the 10 outcomes."),
       Q("Why do more trials help?", ["The results get closer to the true probability", "The program runs faster", "Random becomes exact", "They never help"], 0, "The average of many trials settles near the truth.")]),

    L("7.5", "Search a list with linear search and binary search, and compare how many steps each takes.",
      [("linear search", "check items one at a time from the start"), ("binary search", "look at the middle of a SORTED list and cut the search in half each time"), ("sorted", "in order, such as smallest to largest"), ("efficiency", "how many steps an algorithm needs")],
      [("Linear search with a loop", """To find out whether a list has a target, loop through it and check each item. A flag (`found = False`) is set to `True` when the item matches. This is **linear search**."""),
       ("Make it a procedure, return the position", """Put the search in a procedure. A version that returns the **position** goes through the indexes and returns `i` when it finds the target. If the loop ends without a match, it returns `-1`."""),
       ("Count the checks", """Linear search may check every item. In the worst case (the target is last, or missing) it checks all `n` items. Counting the checks shows how much work it does."""),
       ("Binary search: cut it in half", """If the list is **sorted**, you can do much better. **Binary search** looks at the **middle** item. If it is too small, the target must be in the upper half; if too large, in the lower half. Each look **cuts the list in half**, so even a list of a million items takes about 20 checks."""),
       ("Reasonable or unreasonable?", """An algorithm that takes a reasonable amount of time grows slowly (like linear or binary search). The exam says an algorithm is **reasonable** when its steps grow at most as a polynomial like n or n squared. Binary search needs a sorted list; linear search works on any list."""),
      ],
      [A("Linear search", 'names = ["Ana", "Ben", "Cy", "Dee"]\ntarget = "Cy"\nfound = False\nfor name in names:\n    if name == target:\n        found = True\nprint(found)',
         [(2, "found = False", "Assume not found."), (4, "name == target", "Check each item."), (5, "found = True", "Remember we found it.")], out="True", cap="Linear search checks the items in order."),
       A("Return the position", 'def find_index(items, target):\n    for i in range(len(items)):\n        if items[i] == target:\n            return i\n    return -1\n\nprint(find_index(["a", "b", "c"], "c"))',
         [(2, "items[i] == target", "Compare each item."), (3, "return i", "Give back the position."), (4, "return -1", "Only reached if never found.")], out="2", cap="-1 means not found.")],
      [T("Linear search", 'names = ["Ana", "Ben", "Cy", "Dee"]\ntarget = "Cy"\nfound = False\nfor name in names:\n    if name == target:\n        found = True', ['1| names=["Ana", "Ben", "Cy", "Dee"]', '2| target="Cy"', '3| found=False', '4| name="Ana"', '4| name="Ben"', '4| name="Cy"', '6| found=True', '4| name="Dee"'], cap="The search checks Ana, Ben, then Cy, where found becomes True. This simple version keeps going to Dee anyway."),
       T("Return the position", 'def find_index(items, target):\n    for i in range(len(items)):\n        if items[i] == target:\n            return i\n    return -1\n\nspot = find_index(["a", "b", "c"], "c")\nmiss = find_index(["a", "b", "c"], "z")', ['1|', '7|', '2| items=["a", "b", "c"]; target="c"; i=0', '2| i=1', '2| i=2', '7| spot=2', '8|', '2| items=["a", "b", "c"]; target="z"; i=0', '2| i=1', '2| i=2', '5|', '8| miss=-1'], cap="For c, i reaches 2 and the function returns 2. For z, the loop ends with no match and the function returns -1.", check=False),
       T("Binary search", 'items = [3, 8, 12, 19, 25, 31, 40]\ntarget = 25\nlow = 0\nhigh = 6\nsteps = 0\nwhile low <= high:\n    mid = (low + high) // 2\n    steps = steps + 1\n    if items[mid] == target:\n        break\n    elif items[mid] < target:\n        low = mid + 1\n    else:\n        high = mid - 1', ['1| items=[3, 8, 12, 19, 25, 31, 40]', '2| target=25', '3| low=0', '4| high=6', '5| steps=0', '7| mid=3', '8| steps=1', '12| low=4', '7| mid=5', '8| steps=2', '14| high=4', '7| mid=4', '8| steps=3'], cap="Start in the middle: index 3 holds 19. 19 is less than 25, so low moves to 4. Next middle is index 5, holding 31. Too big, so high moves to 4. Now the middle is index 4, which holds 25: found in 3 checks. Linear search would need 5."),
       T("Counting checks", 'nums = [3, 8, 12, 19, 25, 31, 40]\nsteps = 0\nfor n in nums:\n    steps = steps + 1\n    if n == 40:\n        break', ['1| nums=[3, 8, 12, 19, 25, 31, 40]', '2| steps=0', '3| n=3', '4| steps=1', '3| n=8', '4| steps=2', '3| n=12', '4| steps=3', '3| n=19', '4| steps=4', '3| n=25', '4| steps=5', '3| n=31', '4| steps=6', '3| n=40', '4| steps=7'], cap="Linear search for the last item takes all 7 checks. Binary search would take 3.")],
      [("Binary search on an unsorted list", "It gives wrong answers.", "Sort first, or use linear search"), ("Returning 0 for \"not found\"", "0 is a real position.", "Return -1"), ("Returning inside the loop's else", "The search quits after the first item.", "Only return `-1` after the loop"), ("`if items[i] = target:`", "One equals stores.", "`==`"),
       ("Forgetting `len` in `range(len(items))`", "TypeError.", "`range(len(items))`"), ("Thinking binary search is always faster for tiny lists", "For a few items it does not matter.", "It matters for big lists"), ("`mid = (low + high) / 2`", "A float index is an error.", "Use `//`"), ("Not updating `low` or `high`", "Infinite loop.", "Move one of them each pass")],
      ["Linear search checks one item at a time. Binary search needs a **sorted** list and eliminates half the items each time.", "Questions ask how many checks a search makes in the worst case.", "An algorithm's efficiency is how many steps it uses as the input grows."],
      [Q("What does binary search require?", ["A sorted list", "A list of numbers only", "An empty list", "A loop"], 0, "It needs the list in order."),
       Q("What does `find_index([\"a\", \"b\"], \"z\")` return?", ["0", "-1", "None", "an error"], 1, "Not found returns -1.", 'def find_index(items, target):\n    for i in range(len(items)):\n        if items[i] == target:\n            return i\n    return -1'),
       Q("In the worst case, linear search on 100 items checks...", ["1", "7", "50", "100"], 3, "The target could be last or missing."),
       Q("Each step of binary search...", ["Checks one item", "Cuts the remaining items in half", "Sorts the list", "Doubles the list"], 1, "It eliminates half each time.")]),

    L("7.6", "Explain how a list manages complexity in the Create Task, and write the 2(c) answers.",
      [("data abstraction", "giving a collection of data a name, like a list, so you do not manage each value separately"), ("complexity", "how hard a program is to understand and change"), ("list segment", "one of the two list code segments in your PPR")],
      [("The problem without a list", """Imagine tracking five scores with five variables: `score1`, `score2`, `score3`, `score4`, `score5`. To add them up, you write `score1 + score2 + ...`. For ten scores you write more. Every new score means a **new variable and new code**."""),
       ("The same program with a list", """With a list, `scores = [80, 90, 70, 60, 85]` is one variable. One loop adds them all. The code works for any number of scores."""),
       ("Add an item: the loop does not change", """When you add a sixth score to the list, the loop stays **exactly the same**. That is how a list **manages complexity**: the program does not get bigger as the data does."""),
       ("Pass a list to a procedure", """A list can be a **parameter**: `def average(scores):`. The procedure works on any list you pass in."""),
       ("Write the 2(c) answers", """Say what the list lets the program do (handle any number of items with one loop), and what the code would need without the list (a separate variable and copy of the code for every item). Be specific about your own code."""),
       ("Is your list Create Task ready?", """Check: the list stores **several** items, it is created in one place (**List (i)**), and the same list is **used** in another place (**List (ii)**), for example in a loop."""),
      ],
      [A("With a list", 'scores = [80, 90, 70, 60, 85]\ntotal = 0\nfor s in scores:\n    total = total + s\nprint(total / len(scores))',
         [(0, "[", "One name for all the data."), (2, "for s in scores", "One loop handles every item.")], out="77.0", cap="Add a sixth score and the loop does not change."),
       A("The list as a parameter", 'def average(scores):\n    total = 0\n    for s in scores:\n        total = total + s\n    return total / len(scores)\n\nprint(average([80, 90]))',
         [(0, "scores", "The list is the parameter."), (4, "len(scores)", "Works for any size.")], out="85.0", cap="The procedure works for any list.")],
      [T("Without a list", 'score1 = 80\nscore2 = 90\nscore3 = 70\ntotal = score1 + score2 + score3\navg = total / 3', ['1| score1=80', '2| score2=90', '3| score3=70', '4| total=240', '5| avg=80.0'], cap="Three variables. A fourth score needs a new variable AND changes to lines 4 and 5."),
       T("With a list", 'scores = [80, 90, 70]\ntotal = 0\nfor s in scores:\n    total = total + s\navg = total / len(scores)', ['1| scores=[80, 90, 70]', '2| total=0', '3| s=80', '4| total=80', '3| s=90', '4| total=170', '3| s=70', '4| total=240', '5| avg=80.0'], cap="The same answer, with one variable and one loop."),
       T("A new item and no code change", 'scores = [80, 90, 70, 100]\ntotal = 0\nfor s in scores:\n    total = total + s\navg = total / len(scores)', ['1| scores=[80, 90, 70, 100]', '2| total=0', '3| s=80', '4| total=80', '3| s=90', '4| total=170', '3| s=70', '4| total=240', '3| s=100', '4| total=340', '5| avg=85.0'], cap="A fourth score was added to the list. The loop and the average line are unchanged."),
       T("A list passed to a procedure", 'def biggest(items):\n    best = items[0]\n    for x in items:\n        if x > best:\n            best = x\n    return best\n\nanswer = biggest([4, 9, 2])', ['1|', '8|', '2| items=[4, 9, 2]; best=4', '3| x=4', '3| x=9', '5| best=9', '3| x=2', '6|', '8| answer=9'], cap="The procedure gets the list from its parameter, and the same code works for any list.")],
      [("A list that is created but never used", "The list requirement is not met.", "Loop over it or access items in List (ii)"), ("A list with one item", "It does not show abstraction.", "Store several items"), ("Saying \"the list makes it easier\"", "Too vague for 2(c).", "Say what the list lets the program do and what code would change without it"), ("Showing the same code for List (i) and List (ii)", "One must create the list; the other must use it.", "Show the creation, then the use"),
       ("Hard-coding the length: `range(5)`", "The loop breaks when the list changes size.", "`range(len(scores))` or loop over the list"), ("Comments in the PPR", "Zero on the whole task.", "Remove every comment"), ("A list of unrelated values", "It does not model the data.", "Store related items"), ("Not testing with a different list", "You do not know the procedure works generally.", "Test with more than one list")],
      ["A list manages **complexity** because it lets a program handle many values with one name.", "Data abstraction is part of the Create Task: you must show where the list is created and where it is used.", "Be ready to say how the code would change without the list."],
      [Q("What does a list help with?", ["Managing many values under one name", "Making code run backward", "Avoiding loops", "Adding colors"], 0, "It reduces complexity."),
       Q("A sixth item is added to `scores` and the loop is `for s in scores:`. What changes?", ["The loop must be rewritten", "Nothing", "A new variable is needed", "The list must be sorted"], 1, "The loop handles any number of items."),
       Q("Where must the list be used in your PPR?", ["List (ii)", "Procedure (i)", "Neither", "Video"], 0, "List (ii) shows the list being used."),
       Q("What would you need without the list?", ["A separate variable for each item", "A faster computer", "Nothing", "More comments"], 0, "That is the complexity the list removes.")]),

    L("7.7", "Develop an algorithm from sequencing, selection, and iteration, recognize equivalent algorithms, and test with the right inputs.",
      [("algorithm", "a finite set of instructions that accomplishes a task"), ("equivalent algorithms", "different algorithms that give the same result for every input"), ("edge case", "an extreme input, like an empty list, that may break the algorithm"), ("modify an algorithm", "change an algorithm to do a slightly different job")],
      [],
      [A("An algorithm uses all three building blocks", 'total = 0\nfor n in [3, 4, 6]:\n    if n % 2 == 0:\n        total = total + n\nprint(total)',
         [(0, "total = 0", "SEQUENCING: steps in order."), (1, "for n in", "ITERATION: repeat for every item."), (2, "n % 2 == 0", "SELECTION: only evens.")], out="10", cap="Sum of the even numbers: 4 + 6.")],
      [T("Sum of the evens", 'total = 0\nfor n in [3, 4, 6]:\n    if n % 2 == 0:\n        total = total + n', ['1| total=0', '2| n=3', '2| n=4', '4| total=4', '2| n=6', '4| total=10'], cap="3 is odd and is skipped. 4 and 6 are even and are added."),
       T("Equivalent algorithms: a loop", 'total = 0\nfor i in range(1, 5):\n    total = total + i', ['1| total=0', '2| i=1', '3| total=1', '2| i=2', '3| total=3', '2| i=3', '3| total=6', '2| i=4', '3| total=10'], cap="One way to add 1 through 4."),
       T("Equivalent algorithms: a formula", 'n = 4\ntotal = n * (n + 1) // 2', ['1| n=4', '2| total=10'], cap="A different algorithm with the same result, 10, for every n. They are equivalent even though one loops and one does not."),
       T("A look-alike that is wrong", 'best = 0\nfor n in [-5, -2, -9]:\n    if n > best:\n        best = n', ['1| best=0', '2| n=-5', '2| n=-2', '2| n=-9'], cap="This looks like a largest-item algorithm, but best starts at 0, so for all-negative data it returns 0, which is not in the list. Start with the first item instead."),
       T("An edge case: the empty list", 'nums = []\ntotal = 0\nfor n in nums:\n    total = total + n\navg = total / len(nums)', ['1| nums=[]', '2| total=0'], out="ZeroDivisionError: division by zero", cap="An empty list is an edge case. The loop runs zero times and the division by len(nums) = 0 crashes."),
       T("Modify an algorithm: the spread", 'nums = [4, 9, 2]\nbig = nums[0]\nsmall = nums[0]\nfor n in nums:\n    if n > big:\n        big = n\n    if n < small:\n        small = n\nspread = big - small', ['1| nums=[4, 9, 2]', '2| big=4', '3| small=4', '4| n=4', '4| n=9', '6| big=9', '4| n=2', '8| small=2', '9| spread=7'], cap="Combining two algorithms (largest and smallest) gives a new one: the spread is 9 - 2 = 7.")],
      [("Starting `best = 0` for any data", "Wrong for negative numbers.", "Start with the first item"), ("Testing only with typical data", "Edge cases break the algorithm.", "Test an empty list, one item, and extremes"), ("Thinking different code means different results", "Equivalent algorithms can look very different.", "Compare results for all inputs"), ("Thinking the same results on one input means equivalent", "They may differ on other inputs.", "Test several inputs"),
       ("Forgetting `else` or a case in the selection", "Some inputs are not handled.", "Check every branch"), ("A loop that stops one item early", "The last item is skipped.", "Trace the first and the last pass"), ("Changing the algorithm without retesting", "A modification can break it.", "Retest after every change"), ("Writing an algorithm that never ends", "An algorithm must finish.", "Make sure the loop can stop")],
      [], [],
      src=("gen", algos7, "developing-algorithms")),

    L("7.8", "Compare algorithms by how their steps grow, and tell reasonable time from unreasonable time and heuristics from exact answers.",
      [("efficiency", "how the number of steps grows as the input gets bigger"), ("reasonable time", "steps grow like n, n squared, n cubed, or slower"), ("unreasonable time", "steps grow like 2 to the n or n factorial, which explodes"), ("heuristic", "a good-enough answer found quickly when the best answer takes too long"), ("optimization problem", "a problem that asks for the best answer")],
      [],
      [A("Nested loops: n times n", 'count = 0\nfor i in range(3):\n    for j in range(3):\n        count = count + 1\nprint(count)',
         [(1, "range(3)", "Outer loop: 3 passes."), (2, "range(3)", "Inner loop: 3 passes EACH time.")], out="9", cap="3 times 3 is 9 steps. Double n and the steps quadruple.")],
      [T("Count the steps of a linear search", 'nums = [5, 8, 3, 9, 7, 2, 6, 4]\nsteps = 0\nfor n in nums:\n    steps = steps + 1\n    if n == 4:\n        break', ['1| nums=[5, 8, 3, 9, 7, 2, 6, 4]', '2| steps=0', '3| n=5', '4| steps=1', '3| n=8', '4| steps=2', '3| n=3', '4| steps=3', '3| n=9', '4| steps=4', '3| n=7', '4| steps=5', '3| n=2', '4| steps=6', '3| n=6', '4| steps=7', '3| n=4', '4| steps=8'], cap="The target 4 is last, so a linear search needs 8 steps for 8 items: as many as n."),
       T("Nested loops", 'count = 0\nfor i in range(3):\n    for j in range(3):\n        count = count + 1', ['1| count=0', '2| i=0', '3| j=0', '4| count=1', '3| j=1', '4| count=2', '3| j=2', '4| count=3', '2| i=1', '3| j=0', '4| count=4', '3| j=1', '4| count=5', '3| j=2', '4| count=6', '2| i=2', '3| j=0', '4| count=7', '3| j=1', '4| count=8', '3| j=2', '4| count=9'], cap="The inner loop runs fully for each outer pass: 3 times 3 is 9."),
       T("Halving: how many times can you cut 16 in half?", 'size = 16\nhalvings = 0\nwhile size > 1:\n    size = size // 2\n    halvings = halvings + 1', ['1| size=16', '2| halvings=0', '4| size=8', '5| halvings=1', '4| size=4', '5| halvings=2', '4| size=2', '5| halvings=3', '4| size=1', '5| halvings=4'], cap="16 items need only 4 halvings. This is why binary search is so fast: a million items take about 20."),
       T("Trying every ordering grows explosively", 'orders = 1\nfor stops in range(1, 6):\n    orders = orders * stops', ['1| orders=1', '2| stops=1', '3| orders=1', '2| stops=2', '3| orders=2', '2| stops=3', '3| orders=6', '2| stops=4', '3| orders=24', '2| stops=5', '3| orders=120'], cap="1, 2, 6, 24, 120 orderings. Every extra stop multiplies the work. This is factorial growth, an unreasonable time."),
       T("A heuristic: greedy coins", 'coins = [25, 10, 1]\namount = 30\ncount = 0\nfor c in coins:\n    while amount >= c:\n        amount = amount - c\n        count = count + 1', ['1| coins=[25, 10, 1]', '2| amount=30', '3| count=0', '4| c=25', '6| amount=5', '7| count=1', '4| c=10', '4| c=1', '6| amount=4', '7| count=2', '6| amount=3', '7| count=3', '6| amount=2', '7| count=4', '6| amount=1', '7| count=5', '6| amount=0', '7| count=6'], cap="Always taking the biggest coin is fast and good enough, but here it uses 6 coins. The best answer is 3 dimes. A heuristic is fast but not always the best.")],
      [("Measuring speed with a stopwatch", "A faster computer makes every algorithm faster.", "Compare how the steps GROW with n"), ("Calling 2 to the n \"just a bit slower\"", "It explodes: doubling n squares the work.", "Know reasonable versus unreasonable"), ("\"Unreasonable means impossible\"", "It only means too slow for large inputs.", "Unreasonable is not undecidable"), ("Expecting a heuristic to always be best", "It is only good enough.", "Use it when exact answers take too long"),
       ("Counting exact steps for the exam", "The exam compares growth, not exact counts.", "Say which grows faster"), ("Nested loops treated as n steps", "They are n times n.", "Multiply the loops"), ("Thinking binary search works on any list", "It needs a sorted list.", "Sort first or use linear search"), ("Thinking one run proves efficiency", "Steps depend on input size.", "Think about big n")],
      [], [],
      src=("gen", algos7, "algorithm-efficiency")),

    L("7.9", "Understand that some problems cannot be solved by any algorithm, and tell undecidable from merely hard.",
      [("decidable problem", "an algorithm can always give a correct yes-or-no answer"), ("undecidable problem", "no algorithm can solve it for every input"), ("halting problem", "deciding whether any program will eventually stop or run forever")],
      [],
      [A("A loop nobody can prove stops", 'n = 3\nwhile n != 1:\n    if n % 2 == 0:\n        n = n // 2\n    else:\n        n = 3 * n + 1',
         [(1, "n != 1", "Runs until n reaches 1."), (5, "3 * n + 1", "The odd step.")], cap="Nobody has proved this loop stops for every starting n. (For n = 3 it does.)", check=False)],
      [T("A decidable problem", 'n = 7\nanswer = n % 2 == 0', ['1| n=7', '2| answer=False'], cap="Is n even? An algorithm can always answer yes or no, so this problem is decidable."),
       T("Another decidable problem: is it in the list?", 'items = [4, 9, 2]\nfound = False\nfor x in items:\n    if x == 9:\n        found = True', ['1| items=[4, 9, 2]', '2| found=False', '3| x=4', '3| x=9', '5| found=True', '3| x=2'], cap="Searching a finite list always finishes with a correct yes or no."),
       T("You cannot just run it and see", 'n = 3\nsteps = 0\nwhile n != 1:\n    if n % 2 == 0:\n        n = n // 2\n    else:\n        n = 3 * n + 1\n    steps = steps + 1', ['1| n=3', '2| steps=0', '7| n=10', '8| steps=1', '5| n=5', '8| steps=2', '7| n=16', '8| steps=3', '5| n=8', '8| steps=4', '5| n=4', '8| steps=5', '5| n=2', '8| steps=6', '5| n=1', '8| steps=7'], cap="For n = 3, the loop stops after 7 steps. But running it for some numbers never proves it stops for all numbers. If you just run a program and wait, you cannot tell \"slow\" from \"never\"."),
       T("Hard is not impossible", 'tries = 0\nfor a in range(3):\n    for b in range(3):\n        tries = tries + 1', ['1| tries=0', '2| a=0', '3| b=0', '4| tries=1', '3| b=1', '4| tries=2', '3| b=2', '4| tries=3', '2| a=1', '3| b=0', '4| tries=4', '3| b=1', '4| tries=5', '3| b=2', '4| tries=6', '2| a=2', '3| b=0', '4| tries=7', '3| b=1', '4| tries=8', '3| b=2', '4| tries=9'], cap="Trying every combination of two digits takes 9 tries. It grows fast, but it can be done: hard problems have algorithms, they are just slow. Undecidable problems have no algorithm at all.")],
      [("Confusing unreasonable and undecidable", "Unreasonable is solvable but too slow. Undecidable has no algorithm.", "Ask: does an algorithm exist at all?"), ("\"Just run the program and see if it stops\"", "A program that has not stopped yet may still stop later.", "That is why the halting problem is undecidable"), ("Thinking a faster computer solves it", "Speed cannot fix a problem with no algorithm.", "Undecidable is about possibility, not speed"), ("Thinking all hard problems are impossible", "Many have slow but correct algorithms.", "Hard is not the same as impossible"),
       ("Thinking undecidable means unsolved so far", "It means proved to have no algorithm for all inputs.", "Know the halting problem"), ("Saying an undecidable problem can never be solved for ANY input", "Some inputs can be decided.", "No algorithm works for ALL inputs"), ("Mixing up a decision problem with an optimization problem", "Decision: yes or no. Optimization: best.", "Check the question type"), ("Ignoring the exam's wording", "The exam asks which statement is true about a problem.", "Read each option carefully")],
      [], [],
      src=("gen", algos7, "undecidable-problems")),
    ],
    glossary=[], seed=7)
